// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address deployer, address newOwner) public {
        vm.assume(deployer != address(0));
        vm.prank(deployer);
        Caller helper = new Caller(c);

        bool ok;
        try c.setOwner(address(helper)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "setup transfer to helper must succeed");
        assertTrue(c.owner() == address(helper), "owner should be helper after setup");

        vm.prank(deployer);
        helper.callSetOwner(newOwner);

        assertTrue(c.owner() == newOwner, "owner should equal the provided newOwner after setOwner by a contract caller");
    }
}

contract Caller {
    Owned public c;
    constructor(Owned _c) {
        c = _c;
    }
    function callSetOwner(address _owner) external {
        c.setOwner(_owner);
    }
}
